  v_reference_code := 'AP-' || TO_CHAR(NOW(), 'YYYYMMDDHH24MISS') || '-' ||
                      SUBSTR(REPLACE(gen_random_uuid()::TEXT, '-', ''), 1, 6);

  INSERT INTO app.application_payments (
    application_id,
    student_id,
    university_id,
    amount_due,
    currency,
    payment_reason,
    status,
    reference_code,
    created_by
